    // ---- shared arithmetic ----
    // Sign-extend a 16-bit arena word into the accumulator domain.
    function automatic logic signed [ACCW-1:0] sx(input logic signed [SW-1:0] v);
        begin sx = v; end
    endfunction

    // Saturate a 16-bit arena word (identity widths, kept explicit so a
    // future widening cannot silently change the semantics).
    function automatic logic signed [SW-1:0] cl16(input logic signed [SW-1:0] v,
                                             input logic signed [15:0] lo,
                                             input logic signed [15:0] hi);
        begin
            if (v > hi) cl16 = hi;
            else if (v < lo) cl16 = lo;
            else cl16 = v;
        end
    endfunction

    // The one requantization datapath of the engine, shared by every store in
    // the schedule: p = a*M0 ; r = p>=0 ? 2^(sh-1) : 2^(sh-1)-1 ;
    // q = (p+r)>>>sh ; clamp(q, lo, hi). Both operands are extended to PW so
    // the product is not truncated to an operand width.
    function automatic logic signed [SW-1:0] rq(input logic signed [ACCW-1:0] a_in,
                                                input logic [16:0] m0,
                                                input logic [4:0] sh,
                                                input logic signed [15:0] lo_in,
                                                input logic signed [15:0] hi_in);
        logic signed [PW-1:0] a, m, p, r, q, lo, hi;
        begin
            a  = a_in;
            m  = {{(PW-17){1'b0}}, m0};
            lo = lo_in;
            hi = hi_in;
            p  = a * m;
            r  = (sh == 5'd0) ? {PW{1'b0}} : ((p >= 0) ? (PW_ONE << (sh - 5'd1)) : ((PW_ONE << (sh - 5'd1)) - PW_ONE));
            q  = (p + r) >>> sh;
            if (q > hi) q = hi;
            else if (q < lo) q = lo;
            rq = q[SW-1:0];
        end
    endfunction

    // ---- counters, flags and the one-deep store pipeline ----
    logic [6-1:0] state;
    logic [6-1:0] hold_next;
    logic signed [31:0] cy, cx, oc, ic, t;
    logic signed [31:0] li, oi;
    logic [1:0] eof;
    logic [1:0] ad_ph;
    logic       out_ph;
    logic       done_r;
    logic [AW-1:0] el_mem_addr, el_st_addr;
    logic [16-1:0] el_w_addr;
    logic [11-1:0] el_b_addr;
    logic [11-1:0] el_m_addr;
    logic          el_valid, el_ren, el_first, el_last, el_zero, el_store, el_a_capture;
    logic [2:0]    el_kind;
    logic [4:0]    el_sh;
    logic signed [15:0] el_lo, el_hi;
    logic signed [31:0] sy0, sx0;
    logic ok0;
    logic signed [31:0] sy1, sx1;
    logic ok1;
    logic signed [31:0] sy2, sx2;
    logic ok2;
    logic signed [31:0] sy3, sx3;
    logic ok3;
    logic signed [31:0] sy4, sx4;
    logic ok4;
    logic signed [31:0] sy5, sx5;
    logic ok5;
    logic signed [31:0] sy6, sx6;
    logic ok6;
    logic signed [31:0] sy7, sx7;
    logic ok7;
    logic signed [31:0] sy8, sx8;
    logic ok8;
    logic signed [31:0] sy10, sx10;
    logic ok10;
    logic signed [31:0] sy11, sx11;
    logic ok11;
    logic signed [31:0] sy12, sx12;
    logic ok12;
    logic signed [31:0] sy13, sx13;
    logic ok13;
    logic signed [31:0] sy15, sx15;
    logic ok15;
    logic signed [31:0] sy16, sx16;
    logic ok16;
    logic signed [31:0] sy17, sx17;
    logic ok17;
    logic signed [31:0] sy18, sx18;
    logic ok18;
    logic signed [31:0] sy20, sx20;
    logic ok20;
    logic signed [31:0] sy21, sx21;
    logic ok21;
    logic signed [31:0] sy22, sx22;
    logic ok22;
    logic signed [31:0] sy23, sx23;
    logic ok23;
    logic signed [31:0] sy27, sx27;
    logic ok27;
    logic signed [31:0] sy28, sx28;
    logic ok28;
    logic signed [31:0] sy29, sx29;
    logic ok29;
    logic signed [31:0] sy31, sx31;
    logic ok31;
    logic signed [31:0] sy32, sx32;
    logic ok32;
    logic signed [31:0] sy33, sx33;
    logic ok33;
    logic signed [31:0] sy34, sx34;
    logic ok34;
    logic signed [31:0] sy35, sx35;
    logic ok35;
    logic [4:0]             q_sh;
    logic signed [15:0]     q_lo, q_hi;
    logic [AW-1:0]          q_sa;
    logic [2:0]             q_kind;
    logic                   q_valid, q_first, q_last, q_zero;
    logic signed [ACCW-1:0] acc, a_hold;
    logic signed [LPROD-1:0] x_ext, w_ext, lane_prod;
    logic [2:0]             st_kind;
    logic                   p_valid;
    logic [AW-1:0]          p_addr;
    logic signed [SW-1:0]   p_value;
    logic signed [ACCW-1:0] rq_in;
    logic signed [SW-1:0]   rq_out, st_value;
    logic                   dbg_sel;
    logic                   load_we;
    // ---- one shared multiplier: both operands are extended to LPROD first ----
    // `mem_rdata` is the registered read of the element whose flags sit in q_*:
    // the address stage of cycle k presents act_mem's address and the weight ROM's
    // address for element k, both land in `mem_rdata`/`w_data` for cycle k+1, and the
    // q_* flags were registered from that same cycle - so an extra operand register
    // would hold element k-1 and drift from the flags it is paired with.
    always_comb begin x_ext = mem_rdata; w_ext = w_data; end
    assign lane_prod = x_ext * w_ext;
    wire signed [ACCW-1:0] prod_acc = lane_prod[ACCW-1:0];
    wire signed [ACCW-1:0] acc_base = q_first ? b_data : acc;
    wire signed [ACCW-1:0] acc_next = acc_base + (q_zero ? ACC_ZERO : prod_acc);
    // ---- one shared requantizer behind the store pipeline ----
    assign st_kind = el_store ? KIND_ADD : q_kind;
    always_comb begin
        rq_in = sx(mem_rdata);
        if (st_kind == KIND_ACC) rq_in = acc_next;
    end
    assign rq_out = rq(rq_in, m_data, q_sh, q_lo, q_hi);
    always_comb begin
        unique case (st_kind)
            KIND_ACC:   st_value = rq_out;
            KIND_RQ:    st_value = rq_out;
            KIND_COPY:  st_value = mem_rdata;
            KIND_CLAMP: st_value = cl16(mem_rdata, q_lo, q_hi);
            KIND_ADD:   st_value = a_hold + rq_out;
            default:    st_value = rq_out;
        endcase
    end
    wire store_capture = (q_valid && q_last) || el_store;
    // ---- ports ----
    assign load_we = (state == S_LOAD) && in_valid && in_ready;
    assign mem_wen   = load_we || p_valid;
    assign mem_waddr = load_we ? (IN_BASE + li) : p_addr;
    assign mem_wdata = load_we ? {{8{in_data[7]}}, in_data} : p_value;
    assign dbg_sel = dbg_en && ((state == S_IDLE) || (state == S_HOLD));
    assign mem_raddr = dbg_sel ? dbg_addr : el_mem_addr;
    assign mem_ren   = dbg_sel ? 1'b1 : el_ren;
    assign w_addr = el_w_addr;
    assign b_addr = el_b_addr;
    assign m_addr = el_m_addr;
    assign dbg_data = dbg_sel ? mem_rdata : {SW{1'b0}};
    assign dbg_held = (state == S_HOLD);
    assign in_ready = (state == S_LOAD);
    assign out_valid = (state == S_OUT) && out_ph;
    assign out_data = mem_rdata[7:0];
    assign done = done_r;

    // ---- schedule control: one read port and one store port, muxed per step ----
    always_comb begin
        el_valid = 1'b0; el_ren = 1'b0; el_zero = 1'b0;
        el_first = 1'b0; el_last = 1'b0; el_store = 1'b0; el_a_capture = 1'b0;
        el_kind = KIND_ACC; el_sh = 5'd0; el_lo = 16'sd0; el_hi = 16'sd0;
        el_mem_addr = '0; el_w_addr = '0; el_b_addr = '0; el_m_addr = '0; el_st_addr = '0;
        unique case (state)
            S_LOAD: begin end
            S_OP0: begin
                if (eof == 2'd0) begin
                    el_valid = 1'b1;
                    el_first = (ic == 0) && (t == 0);
                    el_last  = (ic == S0_ICG-1) && (t == S0_TAPS-1);
                    el_kind  = KIND_ACC;
                    el_lo = S0_LO; el_hi = S0_HI; el_sh = S0_SHIFT;
                    el_m_addr = S0_MB + oc;
                    el_b_addr = S0_BB + oc;
                    el_w_addr = S0_WB + ((oc*S0_ICG + ic)*S0_TAPS + t);
                    sy0 = 0; sx0 = 0; ok0 = 1'b1;
                    unique case (t)
                        0: begin
                            sy0 = cy*1 + (-1);
                            sx0 = cx*1 + (-1);
                            if (sy0 < 0) sy0 = -sy0;
                            if (sy0 >= 8) sy0 = 14 - sy0;
                            if (sx0 < 0) sx0 = -sx0;
                            if (sx0 >= 8) sx0 = 14 - sx0;
                            ok0 = 1'b1;
                        end
                        1: begin
                            sy0 = cy*1 + (-1);
                            sx0 = cx*1 + (0);
                            if (sy0 < 0) sy0 = -sy0;
                            if (sy0 >= 8) sy0 = 14 - sy0;
                            if (sx0 < 0) sx0 = -sx0;
                            if (sx0 >= 8) sx0 = 14 - sx0;
                            ok0 = 1'b1;
                        end
                        2: begin
                            sy0 = cy*1 + (-1);
                            sx0 = cx*1 + (1);
                            if (sy0 < 0) sy0 = -sy0;
                            if (sy0 >= 8) sy0 = 14 - sy0;
                            if (sx0 < 0) sx0 = -sx0;
                            if (sx0 >= 8) sx0 = 14 - sx0;
                            ok0 = 1'b1;
                        end
                        3: begin
                            sy0 = cy*1 + (0);
                            sx0 = cx*1 + (-1);
                            if (sy0 < 0) sy0 = -sy0;
                            if (sy0 >= 8) sy0 = 14 - sy0;
                            if (sx0 < 0) sx0 = -sx0;
                            if (sx0 >= 8) sx0 = 14 - sx0;
                            ok0 = 1'b1;
                        end
                        4: begin
                            sy0 = cy*1 + (0);
                            sx0 = cx*1 + (0);
                            if (sy0 < 0) sy0 = -sy0;
                            if (sy0 >= 8) sy0 = 14 - sy0;
                            if (sx0 < 0) sx0 = -sx0;
                            if (sx0 >= 8) sx0 = 14 - sx0;
                            ok0 = 1'b1;
                        end
                        5: begin
                            sy0 = cy*1 + (0);
                            sx0 = cx*1 + (1);
                            if (sy0 < 0) sy0 = -sy0;
                            if (sy0 >= 8) sy0 = 14 - sy0;
                            if (sx0 < 0) sx0 = -sx0;
                            if (sx0 >= 8) sx0 = 14 - sx0;
                            ok0 = 1'b1;
                        end
                        6: begin
                            sy0 = cy*1 + (1);
                            sx0 = cx*1 + (-1);
                            if (sy0 < 0) sy0 = -sy0;
                            if (sy0 >= 8) sy0 = 14 - sy0;
                            if (sx0 < 0) sx0 = -sx0;
                            if (sx0 >= 8) sx0 = 14 - sx0;
                            ok0 = 1'b1;
                        end
                        7: begin
                            sy0 = cy*1 + (1);
                            sx0 = cx*1 + (0);
                            if (sy0 < 0) sy0 = -sy0;
                            if (sy0 >= 8) sy0 = 14 - sy0;
                            if (sx0 < 0) sx0 = -sx0;
                            if (sx0 >= 8) sx0 = 14 - sx0;
                            ok0 = 1'b1;
                        end
                        8: begin
                            sy0 = cy*1 + (1);
                            sx0 = cx*1 + (1);
                            if (sy0 < 0) sy0 = -sy0;
                            if (sy0 >= 8) sy0 = 14 - sy0;
                            if (sx0 < 0) sx0 = -sx0;
                            if (sx0 >= 8) sx0 = 14 - sx0;
                            ok0 = 1'b1;
                        end
                        default: begin ok0 = 1'b0; sy0 = 0; sx0 = 0; end
                    endcase
                    el_zero = ~ok0;
                    el_mem_addr = ok0 ? (S0_IB + (ic*S0_IH + sy0)*S0_IW + sx0) : '0;
                    el_ren = 1'b1;
                    el_st_addr = S0_OB + (oc*S0_OH + cy)*S0_OW + cx;
                end
            end
            S_OP1: begin
                if (eof == 2'd0) begin
                    el_valid = 1'b1;
                    el_first = (t == 0);
                    el_last  = (t == S1_TAPS-1);
                    el_kind  = KIND_ACC;
                    el_lo = S1_LO; el_hi = S1_HI; el_sh = S1_SHIFT;
                    el_m_addr = S1_MB + oc;
                    el_b_addr = S1_BB + oc;
                    el_w_addr = S1_WB + oc*S1_TAPS + t;
                    sy1 = 0; sx1 = 0; ok1 = 1'b1;
                    unique case (t)
                        0: begin
                            sy1 = cy*2 + (-1);
                            sx1 = cx*2 + (-1);
                            if (sy1 < 0) sy1 = -sy1;
                            if (sy1 >= 8) sy1 = 14 - sy1;
                            if (sx1 < 0) sx1 = -sx1;
                            if (sx1 >= 8) sx1 = 14 - sx1;
                            ok1 = 1'b1;
                        end
                        1: begin
                            sy1 = cy*2 + (-1);
                            sx1 = cx*2 + (0);
                            if (sy1 < 0) sy1 = -sy1;
                            if (sy1 >= 8) sy1 = 14 - sy1;
                            if (sx1 < 0) sx1 = -sx1;
                            if (sx1 >= 8) sx1 = 14 - sx1;
                            ok1 = 1'b1;
                        end
                        2: begin
                            sy1 = cy*2 + (-1);
                            sx1 = cx*2 + (1);
                            if (sy1 < 0) sy1 = -sy1;
                            if (sy1 >= 8) sy1 = 14 - sy1;
                            if (sx1 < 0) sx1 = -sx1;
                            if (sx1 >= 8) sx1 = 14 - sx1;
                            ok1 = 1'b1;
                        end
                        3: begin
                            sy1 = cy*2 + (0);
                            sx1 = cx*2 + (-1);
                            if (sy1 < 0) sy1 = -sy1;
                            if (sy1 >= 8) sy1 = 14 - sy1;
                            if (sx1 < 0) sx1 = -sx1;
                            if (sx1 >= 8) sx1 = 14 - sx1;
                            ok1 = 1'b1;
                        end
                        4: begin
                            sy1 = cy*2 + (0);
                            sx1 = cx*2 + (0);
                            if (sy1 < 0) sy1 = -sy1;
                            if (sy1 >= 8) sy1 = 14 - sy1;
                            if (sx1 < 0) sx1 = -sx1;
                            if (sx1 >= 8) sx1 = 14 - sx1;
                            ok1 = 1'b1;
                        end
                        5: begin
                            sy1 = cy*2 + (0);
                            sx1 = cx*2 + (1);
                            if (sy1 < 0) sy1 = -sy1;
                            if (sy1 >= 8) sy1 = 14 - sy1;
                            if (sx1 < 0) sx1 = -sx1;
                            if (sx1 >= 8) sx1 = 14 - sx1;
                            ok1 = 1'b1;
                        end
                        6: begin
                            sy1 = cy*2 + (1);
                            sx1 = cx*2 + (-1);
                            if (sy1 < 0) sy1 = -sy1;
                            if (sy1 >= 8) sy1 = 14 - sy1;
                            if (sx1 < 0) sx1 = -sx1;
                            if (sx1 >= 8) sx1 = 14 - sx1;
                            ok1 = 1'b1;
                        end
                        7: begin
                            sy1 = cy*2 + (1);
                            sx1 = cx*2 + (0);
                            if (sy1 < 0) sy1 = -sy1;
                            if (sy1 >= 8) sy1 = 14 - sy1;
                            if (sx1 < 0) sx1 = -sx1;
                            if (sx1 >= 8) sx1 = 14 - sx1;
                            ok1 = 1'b1;
                        end
                        8: begin
                            sy1 = cy*2 + (1);
                            sx1 = cx*2 + (1);
                            if (sy1 < 0) sy1 = -sy1;
                            if (sy1 >= 8) sy1 = 14 - sy1;
                            if (sx1 < 0) sx1 = -sx1;
                            if (sx1 >= 8) sx1 = 14 - sx1;
                            ok1 = 1'b1;
                        end
                        default: begin ok1 = 1'b0; sy1 = 0; sx1 = 0; end
                    endcase
                    el_zero = ~ok1;
                    el_mem_addr = ok1 ? (S1_IB + (oc*S1_IH + sy1)*S1_IW + sx1) : '0;
                    el_ren = 1'b1;
                    el_st_addr = S1_OB + (oc*S1_OH + cy)*S1_OW + cx;
