                    el_kind  = KIND_ACC;
                    el_lo = S2_LO; el_hi = S2_HI; el_sh = S2_SHIFT;
                    el_m_addr = S2_MB + oc;
                    el_b_addr = S2_BB + oc;
                    el_w_addr = S2_WB + ((oc*S2_ICG + ic)*S2_TAPS + t);
                    sy2 = 0; sx2 = 0; ok2 = 1'b1;
                    unique case (t)
                        0: begin
                            sy2 = cy*1 + (0);
                            sx2 = cx*1 + (0);
                            ok2 = (sy2 >= 0) && (sy2 < 4) && (sx2 >= 0) && (sx2 < 4);
                        end
