                    endcase
                    el_zero = ~ok2;
                    el_mem_addr = ok2 ? (S2_IB + (ic*S2_IH + sy2)*S2_IW + sx2) : '0;
                    el_ren = 1'b1;
                    el_st_addr = S2_OB + (oc*S2_OH + cy)*S2_OW + cx;
                end
            end
            S_OP3: begin
                if (eof == 2'd0) begin
                    el_valid = 1'b1;
                    el_first = (t == 0);
                    el_last  = (t == S3_TAPS-1);
                    el_kind  = KIND_ACC;
                    el_lo = S3_LO; el_hi = S3_HI; el_sh = S3_SHIFT;
                    el_m_addr = S3_MB + oc;
                    el_b_addr = S3_BB + oc;
                    el_w_addr = S3_WB + oc*S3_TAPS + t;
                    sy3 = 0; sx3 = 0; ok3 = 1'b1;
                    unique case (t)
                        0: begin
                            sy3 = cy*2 + (-1);
                            sx3 = cx*2 + (-1);
                            if (sy3 < 0) sy3 = -sy3;
                            if (sy3 >= 4) sy3 = 6 - sy3;
                            if (sx3 < 0) sx3 = -sx3;
                            if (sx3 >= 4) sx3 = 6 - sx3;
                            ok3 = 1'b1;
                        end
                        1: begin
                            sy3 = cy*2 + (-1);
                            sx3 = cx*2 + (0);
                            if (sy3 < 0) sy3 = -sy3;
                            if (sy3 >= 4) sy3 = 6 - sy3;
                            if (sx3 < 0) sx3 = -sx3;
                            if (sx3 >= 4) sx3 = 6 - sx3;
                            ok3 = 1'b1;
                        end
                        2: begin
                            sy3 = cy*2 + (-1);
                            sx3 = cx*2 + (1);
                            if (sy3 < 0) sy3 = -sy3;
                            if (sy3 >= 4) sy3 = 6 - sy3;
                            if (sx3 < 0) sx3 = -sx3;
                            if (sx3 >= 4) sx3 = 6 - sx3;
                            ok3 = 1'b1;
                        end
                        3: begin
                            sy3 = cy*2 + (0);
                            sx3 = cx*2 + (-1);
                            if (sy3 < 0) sy3 = -sy3;
                            if (sy3 >= 4) sy3 = 6 - sy3;
                            if (sx3 < 0) sx3 = -sx3;
                            if (sx3 >= 4) sx3 = 6 - sx3;
                            ok3 = 1'b1;
                        end
                        4: begin
                            sy3 = cy*2 + (0);
                            sx3 = cx*2 + (0);
                            if (sy3 < 0) sy3 = -sy3;
                            if (sy3 >= 4) sy3 = 6 - sy3;
                            if (sx3 < 0) sx3 = -sx3;
                            if (sx3 >= 4) sx3 = 6 - sx3;
                            ok3 = 1'b1;
                        end
                        5: begin
                            sy3 = cy*2 + (0);
                            sx3 = cx*2 + (1);
                            if (sy3 < 0) sy3 = -sy3;
                            if (sy3 >= 4) sy3 = 6 - sy3;
                            if (sx3 < 0) sx3 = -sx3;
                            if (sx3 >= 4) sx3 = 6 - sx3;
                            ok3 = 1'b1;
                        end
                        6: begin
                            sy3 = cy*2 + (1);
                            sx3 = cx*2 + (-1);
                            if (sy3 < 0) sy3 = -sy3;
                            if (sy3 >= 4) sy3 = 6 - sy3;
                            if (sx3 < 0) sx3 = -sx3;
                            if (sx3 >= 4) sx3 = 6 - sx3;
                            ok3 = 1'b1;
                        end
                        7: begin
                            sy3 = cy*2 + (1);
                            sx3 = cx*2 + (0);
                            if (sy3 < 0) sy3 = -sy3;
                            if (sy3 >= 4) sy3 = 6 - sy3;
                            if (sx3 < 0) sx3 = -sx3;
                            if (sx3 >= 4) sx3 = 6 - sx3;
                            ok3 = 1'b1;
                        end
                        8: begin
                            sy3 = cy*2 + (1);
                            sx3 = cx*2 + (1);
                            if (sy3 < 0) sy3 = -sy3;
                            if (sy3 >= 4) sy3 = 6 - sy3;
                            if (sx3 < 0) sx3 = -sx3;
                            if (sx3 >= 4) sx3 = 6 - sx3;
                            ok3 = 1'b1;
                        end
                        default: begin ok3 = 1'b0; sy3 = 0; sx3 = 0; end
